def extract_spdx_header(path: Path) -> str | None:
    """Extract SPDX license identifier from file header or return None."""
    raw = path.read_text(encoding="utf-8", errors="replace")
    lines = raw.splitlines()
    for line in lines[:10]:
        line = line.strip()
        if line.startswith("# SPDX-License-Identifier:"):
            return line.split(":", 1)[1].strip()
    return None


def validate_spdx_headers(root: Path) -> dict[str, list[str]]:
    """Validate SPDX headers in all .py files under root directory."""
    results: dict[str, list[str]] = {}
    for py_file in sorted(root.rglob("*.py")):
        if py_file.is_symlink():
            continue
        identifier = extract_spdx_header(py_file)
        if identifier:
            results[str(py_file.relative_to(root))] = [identifier]
        else:
            results[str(py_file.relative_to(root))] = ["MISSING"]
    return results


def main() -> None:
    root = Path("E:\\Github\\srinivasan-78-github-io")
    if not root.exists():
        print(f"Directory not found: {root}")
        return

    headers = validate_spdx_headers(root)
    missing = [f for f, ids in headers.items() if ids[0] == "MISSING"]

    if missing:
        print("Files missing SPDX license identifiers:")
        for f in missing:
            print(f"  {f}: {headers[f]}")
        print(f"\nTotal: {len(missing)} of {len(headers)} files")
    else:
        print("All files have valid SPDX license identifiers.")
        print(f"Total: {len(headers)} files")
